// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address actor) public {
        // The pause state of a freshly deployed (never-paused) contract must be
        // readable as false from any caller; paused() must reflect the actual
        // internal _paused flag, which starts at false.
        vm.prank(actor);
        bool reported = c.paused();
        assertTrue(reported == false, "unpaused contract must report paused() == false");
    }
}
